// 1. Pega os itens de entrada do nó atual (a resposta da Jina)
const items = $input.all();
const resultadosLimpos = [];

// 2. Resgata a query exata do nó "Google Search Scrapper"
// Usando a sintaxe oficial do n8n para referenciar nós anteriores
const queryOriginal = $('Google Search Scrapper').first().json.body.queries || "";

for (const item of items) {
  // A Jina Search devolve os resultados dentro da array 'data'
  const searchResults = item.json.data || [];

  if (Array.isArray(searchResults)) {
    for (const result of searchResults) {

      // Pula páginas que falharam no scraping (status 400+, 429, 403, etc.)
      if (result.httpStatus && result.httpStatus >= 400) {
        continue;
      }

      let rawMarkdown = result.content || "";

      if (rawMarkdown) {
        // --- A FAXINA (REGEX) ---

        // A. Remove completamente as tags de imagem em Markdown: ![Imagem 1](https://url...)
        rawMarkdown = rawMarkdown.replace(/!\[.*?\]\(.*?\)/g, '');

        // B. Remove os links em Markdown, MAS MANTÉM O TEXTO.
        // Exemplo: [Facebook](https://fb.com) vira apenas "Facebook"
        rawMarkdown = rawMarkdown.replace(/\[([^\]]+)\]\([^\)]+\)/g, '$1');

        // C. Remove links puros "http..." jogados no meio do texto
        rawMarkdown = rawMarkdown.replace(/(https?:\/\/[^\s]+)/g, '');

        // D. Limpa marcas/frases de cookies e popups conhecidos
        const lixoComum = /Gerir opções|Aceitar Negar|Gerir serviços|Estatísticas|Marketing|Preferências/gi;
        rawMarkdown = rawMarkdown.replace(lixoComum, '');

        // E. Remove linhas vazias excessivas (3 ou mais sobram apenas 2)
        rawMarkdown = rawMarkdown.replace(/\n{3,}/g, '\n\n');
      }

      // Garante que só inclui resultados com conteúdo textual real
      if (rawMarkdown.trim().length > 0) {
        resultadosLimpos.push({
          json: {
            query: queryOriginal,
            title: result.title || "",
            url: result.url || "",
            texto_limpo: rawMarkdown.trim()
          }
        });
      }
    }
  }
}

return resultadosLimpos;

// 1. Pega todos os itens da entrada (linhas da status_pesquisa)
const items = $input.all();

if (items.length === 0) {
  return [];
}

// 2. Verifica se 100% dos itens possuem o status "auditar" OU "ok" E não estão processando
const todosProntos = items.every(item => 
  ['auditar', 'ok'].includes(item.json.status) && 
  item.json.Processando === false
);

// 3. Se faltar qualquer um (ex: status 'pendente', ou Processando: true), encerra em silêncio (retorna array vazio)
if (!todosProntos) {
  return [];
}

// 4. Se TODOS estiverem validados e com Processando false, pega o id_pesquisa do primeiro item
const idPesquisa = items[0].json.id_pesquisa;

// 5. Retorna UM ÚNICO ITEM contendo o id_pesquisa para liberar os próximos nós
return [
  {
    json: {
      id_pesquisa: idPesquisa,
      total_subtopicos: items.length,
      status_geral: "todos_prontos"
    }
  }
];

